#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Every invocation is a NEW acceptance run, never a resume/reset of old data.
# This section deliberately does not use banner's browser/resume wording.
repo_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)
binary="$repo_root/target/debug/sqlite-workbench"
run_dir=""
report=""
app_pid=""
complete=no

fail() {
  warn "$1"
  if [[ -n "$report" ]]; then
    printf '\n- Failure at stage %s: %s\n' "$_STAGE_INDEX" "$1" >> "$report"
  fi
  exit 1
}

cleanup() {
  local exit_code=$?
  trap - EXIT INT TERM
  if [[ "$complete" != yes ]]; then
    if [[ -n "$report" ]]; then
      printf '\n## INCOMPLETE / ABORTED\n\nExit code: %s. Native acceptance did not pass.\n' "$exit_code" >> "$report"
    fi
    if [[ -n "$app_pid" ]]; then
      warn "Aborted run: cleaning up launch PID $app_pid; this is NOT normal-close evidence."
      if [[ -n "$report" ]]; then
        printf '\n- Abort cleanup requested termination of PID %s; not counted as native exit.\n' "$app_pid" >> "$report"
      fi
      kill -TERM "$app_pid" 2>/dev/null || true
      # No sleeps/polling, and never leave an abort-owned process unmanaged.
      kill -KILL "$app_pid" 2>/dev/null || true
      wait "$app_pid" 2>/dev/null || true
      app_pid=""
    fi
    [[ "$exit_code" -ne 0 ]] || exit_code=1
  fi
  if [[ -n "$run_dir" ]]; then
    say "All evidence and the isolated database are retained: $run_dir"
    say "Report: $report"
  fi
  exit "$exit_code"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# The library's confirm accepts any y-prefix. Native evidence needs ONLY y/yes
# and must fail closed on EOF; keep that stricter behavior below the marker.
confirm_native() {
  local reply=""
  printf '  %s? %s [type y or yes; anything else aborts]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || fail "Input ended before confirmation: $1"
  case "$reply" in
    y|Y|[Yy][Ee][Ss]) return 0 ;;
    *) fail "Not confirmed: $1" ;;
  esac
}

verified_observation() {
  local key="$1" description="$2"
  confirm_native "$description"
  write_env "$key" yes
  printf -- '- Human-reported: %s\n' "$description" >> "$report"
}

cli_expect() {
  local label="$1" sql="$2" expected="$3" actual
  while [[ ! -f "$db" ]]; do
    warn "The expected database does not exist yet: $db"
    say "Keep this guide open. Switch to the native app and activate Open Demo Database."
    say "Wait until its status says 'Demo database connected', then verify the displayed path."
    say "If the app shows an opening error, answer no and share that error and the launch log."
    confirm_native "Recheck the file after you have opened the demo and checked its connected status"
  done
  printf '\n### Independent read-only CLI: %s\n\n' "$label" >> "$report"
  printf '```bash\nsqlite3 -readonly %q %q\n```\n' "$db" "$sql" >> "$report"
  if ! actual=$(sqlite3 -readonly "$db" "$sql" 2>> "$run_dir/cli.stderr.log"); then
    fail "Read-only CLI failed: $label (see cli.stderr.log)"
  fi
  printf 'Actual output:\n```text\n%s\n```\n' "$actual" >> "$report"
  say "CLI ($label):"
  printf '%s\n' "$actual"
  [[ "$actual" == "$expected" ]] || fail "CLI mismatch: $label; expected '$expected'"
  printf -- '- Independently verified by CLI: %s\n\n' "$label" >> "$report"
}

launch_native() {
  local cwd="$1" number="$2" logfile="$run_dir/launch-$2.log"
  [[ -z "$app_pid" ]] || fail "Previous launch has not been reaped"
  printf '\n### Launch %s\n\nWorking directory: %s\n\n' "$number" "$cwd" >> "$report"
  # This is the exact shell sequence used, with an absolute binary/data path.
  printf '```bash\npushd %q\n%q --demo-data-dir %q > %q 2>&1 &\napp_pid=$!\npopd\n```\n' \
    "$cwd" "$binary" "$run_dir" "$logfile" >> "$report"
  pushd "$cwd" >/dev/null
  "$binary" --demo-data-dir "$run_dir" > "$logfile" 2>&1 &
  app_pid=$!
  popd >/dev/null
  printf '\n- Started PID: %s; combined stdout/stderr: %s\n' "$app_pid" "$logfile" >> "$report"
  say "Launched native window (PID $app_pid); log: $logfile"
  say "Expected full database path: $db"
}

wait_native_exit() {
  local number="$1" pid="$app_pid" exit_code=0
  [[ -n "$pid" ]] || fail "No launch PID to wait for"
  say "Waiting for actual native process exit; no kill is used for this check."
  say "If closing the window did not exit the app, press Ctrl-C: the run stays incomplete."
  wait "$pid" || exit_code=$?
  app_pid=""
  printf '\n- Process-verified: launch %s PID %s exited with code %s (wait; no kill).\n' \
    "$number" "$pid" "$exit_code" >> "$report"
  [[ "$exit_code" -eq 0 ]] || fail "Launch $number exited abnormally with code $exit_code"
  write_env "LAUNCH_${number}_NORMAL_EXIT" yes
}

ui_sql() {
  say "Replace ALL SQL editor text with this ONE statement, then activate Run:"
  printf '\n%s\n\n' "$1"
}

stage "Prepare and launch a fresh isolated demo"
say "Seven native acceptance stages. You operate the actual desktop window, not a browser."
say "Every invocation creates a new directory; nothing is resumed, reset, or deleted."
say "Confirm only observations you actually made. No/EOF/Ctrl-C leaves an incomplete report."
for dependency in cargo git sqlite3; do
  command -v "$dependency" >/dev/null 2>&1 || fail "Required command not found: $dependency"
done
# Refuse the current legacy entry point, which silently ignores CLI arguments
# and would otherwise open normal user data. The flag's implementation is a
# prerequisite supplied separately; this wizard never edits the application.
grep -Fq -- '--demo-data-dir' "$repo_root/src/main.rs" || \
  fail "Native entry point must support --demo-data-dir ABSOLUTE_DIR before running this wizard"
sqlite_help=$(sqlite3 -help 2>&1 || true)
[[ "$sqlite_help" == *-readonly* ]] || fail "sqlite3 must support -readonly"
confirm_native "Start a NEW isolated native acceptance run (public observations only)"
run_dir=$(mktemp -d "${TMPDIR:-/tmp}/sqlite-workbench-native.XXXXXX")
run_dir=$(cd -- "$run_dir" && pwd -P)
db="$run_dir/demo.sqlite3"
report="$run_dir/acceptance.md"
ENV_FILE="$run_dir/observations.env"
[[ ! -e "$db" && ! -L "$db" ]] || fail "Fresh database path already exists"
revision=$(git -C "$repo_root" rev-parse HEAD)
dirty_status=$(git -C "$repo_root" status --short --untracked-files=all)
{
  printf '# Native demo acceptance\n\nStatus: PENDING; only the final PASSED section completes this run.\n\n'
  printf 'Started UTC: %s\nRevision: %s\nRepository: %s\nBinary: %s\n' \
    "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" "$revision" "$repo_root" "$binary"
  printf 'Full database file: %s\nFirst cwd: %s\nSecond cwd: %s\nObservations: %s\n\n' \
    "$db" "$repo_root" "$run_dir" "$ENV_FILE"
  printf 'Git dirty status (including untracked files; empty means clean):\n```text\n%s\n```\n' "$dirty_status"
  printf '\nPlatform (uname):\n```text\n%s\n```\n' "$(uname -a)"
  if command -v sw_vers >/dev/null 2>&1; then
    printf '\nPlatform (sw_vers):\n```text\n'
    sw_vers
    printf '```\n'
  fi
  printf '\nSQLite CLI version:\n```text\n%s\n```\n' "$(sqlite3 -version)"
  printf '\nHuman-reported observations are not tool-observed UI evidence. CLI checks only read this file.\n'
  printf 'Build uses the current checkout, including any dirty changes; HEAD alone does not identify those changes.\n'
  printf '\n### Build\n\n```bash\npushd %q\ncargo build --locked > %q 2>&1\npopd\n```\n' \
    "$repo_root" "$run_dir"/build.log
} > "$report"
write_env RUN_DIR "$run_dir"
write_env DATABASE_FILE "$db"
write_env REVISION "$revision"
say "Building before any native launch; build log: $run_dir/build.log"
pushd "$repo_root" >/dev/null
if ! cargo build --locked > "$run_dir/build.log" 2>&1; then
  popd >/dev/null
  fail "cargo build --locked failed; see build.log"
fi
popd >/dev/null
[[ -x "$binary" ]] || fail "Expected native binary is missing: $binary"
printf '\n- Process-verified: cargo build --locked succeeded.\n' >> "$report"
[[ ! -e "$db" && ! -L "$db" ]] || fail "Database unexpectedly exists before first launch"
launch_native "$repo_root" 1
step "Before connecting, verify Run is unavailable. Use Tab/Shift-Tab to reach Open Demo Database."
step "Activate it using Space/Enter (no mouse); observe visible focus. Stop if it cannot be reached."
step "Wait for the status bar to say 'Demo database connected' BEFORE answering the next prompts."
step "A yes answer records your observation; it does not open the database for you."
verified_observation OPEN_KEYBOARD "Run was unavailable before connection, and keyboard focus/activation opened the demo"
step "Verify explorer shows notes and EXACTLY the full path printed above; never accept the normal user-data path."
verified_observation FRESH_OPEN "Native demo opened at the exact isolated database path with the notes table"
cli_expect "fresh seed IDs and bodies" 'SELECT id, body FROM notes ORDER BY id;' \
