verified_observation SEED_PREVIEW "Native Notes preview displayed exactly the two seeded notes checked by CLI"

stage "Read, insert, update, and read back"
ui_sql 'SELECT id, body FROM notes ORDER BY id;'
verified_observation INITIAL_READ "Read displayed id/body headers, the two seeded rows, and Query complete: 2 rows"
ui_sql "INSERT INTO notes (body) VALUES ('Persistence demo');"
verified_observation INSERT_UI "INSERT displayed Write committed: 1 rows affected"
