cli_expect "same full file retains updated row after restart" 'SELECT id, body FROM notes ORDER BY id;' \
  $'1|Welcome to SQLite Workbench\n2|Your changes stay in this local file\n3|Persistence verified'

stage "Delete only the acceptance note through the UI"
confirm_native "Delete ONLY id 3 / Persistence verified in this isolated demo through the UI"
ui_sql "DELETE FROM notes WHERE id = 3 AND body = 'Persistence verified';"
verified_observation DELETE_UI "UI DELETE displayed Write committed: 1 rows affected"
