say "Report: $report"
say "Observations: $ENV_FILE; launch logs: $run_dir/launch-1.log and launch-2.log"
say "Optional notes are PUBLIC. Do not paste secrets. Leave blank for none."
ask ACCEPTANCE_NOTES "Additional context about your observations:"
write_env ACCEPTANCE_NOTES "$ACCEPTANCE_NOTES"
printf '\n### Additional human-reported context\n\n```text\n%s\n```\n' "${ACCEPTANCE_NOTES:-None supplied}" >> "$report"
verified_observation FINAL_REVIEW "Reviewed the report; every recorded human observation was actually performed and passed"
write_env ACCEPTANCE_COMPLETE yes
printf '\n## PASSED\n\nCompleted UTC: %s\n\nAll seven stages passed their explicit human gates and independent CLI/process checks.\n' \
